module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output q
);
    assign q = (a | b) & (c | d);
endmodule

module tb_TopModule;
    reg a, b, c, d;
    wire q;

    TopModule uut (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .q(q)
    );

    integer i;
    reg [3:0] expected_table;

    initial begin
        // Check all 16 combinations
        for (i = 0; i < 16; i = i + 1) {a, b, c, d} = i[3:0];
            #10;
            // Independent expected value calculation
            expected_table = (i[3] | i[2]) & (i[1] | i[0]);
            if (q !== expected_table) begin
                $display("SELFFAIL: a=%b b=%b c=%b d=%b -> q=%b (expected %b)", a, b, c, d, q, expected_table);
                $display("SELFTEST FAIL: mismatch");
                $finish;
            end
        end
        $display("SELFTEST PASS");
        $finish;
    end
endmodule

